"""Signal dictionary lookup (generated by scripts/ghost/build_dictionary.py on the host)."""

from __future__ import annotations

import difflib
import json
import os
import re
from pathlib import Path
from typing import Any

_HERE = Path(__file__).resolve().parent
_CANDIDATES = [
    os.environ.get("GHOST_DATA_DIR", ""),
    "/workspace/ghost",
    str(_HERE.parents[1] / "data" / "ghost"),
]

SYNONYMS = {
    "temp": "temperature",
    "temps": "temperature",
    "press": "pressure",
    "pres": "pressure",
    "vac": "vacuum",
    "comp": "compressor",
    "freq": "frequency",
    "hz": "frequency",
    "lvl": "level",
    "lh": "lockhopper",
    "hopper": "lockhopper",
    "vfd": "frequency",
    "rh": "humidity",
    "co2": "co2",
    "bop": "bop",
    "container": "bop",
    "valve": "valve",
}

_HOST_SYSTEM = {"airbed-host": "airbed", "bop-host": "bop", "lichost": "liquefaction"}

_cache: dict[str, Any] | None = None
_cache_mtime: float = 0.0


def dictionary_path() -> Path | None:
    for base in _CANDIDATES:
        if base and (Path(base) / "signals.json").exists():
            return Path(base) / "signals.json"
    return None


def load() -> dict[str, Any]:
    global _cache, _cache_mtime
    path = dictionary_path()
    if path is None:
        raise FileNotFoundError(
            "signal dictionary not found (expected /workspace/ghost/signals.json; "
            "host job scripts/ghost/build_dictionary.py generates it)"
        )
    mtime = path.stat().st_mtime
    if _cache is None or mtime != _cache_mtime:
        _cache = json.loads(path.read_text(encoding="utf-8"))
        _cache_mtime = mtime
        _index(_cache)
    return _cache


def _tokens(text: str) -> list[str]:
    raw = re.split(r"[^a-z0-9]+", (text or "").lower())
    return [SYNONYMS.get(t, t) for t in raw if t]


def _index(d: dict[str, Any]) -> None:
    for s in d.get("signals", []):
        blob = " ".join(
            str(s.get(k, ""))
            for k in ("id", "gui_label", "gui_section", "group", "description", "tag", "doc", "read_path")
        )
        s["_tokens"] = set(_tokens(blob))
    d["_by_id"] = {s["id"]: s for s in d.get("signals", [])}


def system_for_host(host: str) -> str | None:
    return _HOST_SYSTEM.get(host)


def public(sig: dict[str, Any]) -> dict[str, Any]:
    return {k: v for k, v in sig.items() if not k.startswith("_")}


def _normalize_query(q: str) -> str:
    q = q.strip()
    q = re.sub(r"^co3ntrol_", "", q, flags=re.I)
    q = re.sub(r"^app\.(system\.)?", "", q, flags=re.I)
    return q


def score(sig: dict[str, Any], query: str, qtokens: list[str]) -> float:
    ql = query.lower()
    exact_fields = [
        sig["id"].lower(),
        sig["field"].lower(),
        sig.get("sql", "").lower(),
        sig.get("prom", "").lower(),
        str(sig.get("tag", "")).lower(),
        str(sig.get("gui_label", "")).lower(),
    ]
    if ql in exact_fields or _normalize_query(ql) in exact_fields:
        return 100.0
    if ql and (sig["id"].lower().endswith("." + ql) or sig.get("prom", "").lower().endswith("_" + ql)):
        return 90.0
    toks = sig.get("_tokens", set())
    if not qtokens:
        return 0.0
    overlap = sum(1 for t in qtokens if t in toks)
    partial = sum(0.5 for t in qtokens if t not in toks and any(t in x for x in toks if len(t) >= 3))
    base = (overlap + partial) / len(qtokens) * 60.0
    ratio = difflib.SequenceMatcher(None, "_".join(qtokens), sig["field"].lower()).ratio() * 25.0
    return base + ratio


def lookup(
    query: str,
    system: str = "",
    limit: int = 8,
    deployed_only: bool = False,
    prefer_system: str = "",
) -> dict[str, Any]:
    d = load()
    q = _normalize_query(query)
    qtokens = _tokens(q)
    sys_filter = system.strip().lower()
    if sys_filter in ("container", "container-ship", "bop-host"):
        sys_filter = "bop"
    if sys_filter in ("airbed-host",):
        sys_filter = "airbed"
    if sys_filter in ("liq", "lichost"):
        sys_filter = "liquefaction"

    ranked: list[tuple[float, dict[str, Any]]] = []
    for s in d.get("signals", []):
        if sys_filter and s["system"] != sys_filter and not (sys_filter == "bop" and s["system"] == "dacs"):
            continue
        if deployed_only and not s.get("deployed_on"):
            continue
        sc = score(s, q, qtokens)
        if sc < 20:
            continue
        if s.get("deployed_on"):
            sc += 5
        if prefer_system and s["system"] in (prefer_system, "supervisor") or (
            prefer_system == "bop" and s["system"] == "dacs"
        ):
            sc += 8
        ranked.append((sc, s))
    ranked.sort(key=lambda x: -x[0])

    rules = []
    ql = q.lower()
    for r in d.get("rules", []):
        names = [r["name"]] + [ra.get("recovery", "") for ra in r.get("recovery_actions", [])]
        if any(ql == n or (len(ql) >= 4 and ql in n) for n in names if n) or (
            qtokens and all(t in r["name"] for t in qtokens)
        ):
            rules.append({k: v for k, v in r.items() if k != "source"} | {"source_excerpt": r.get("source", "")[:2500]})

    if rules and any(r["name"] == ql for r in rules):
        ranked = [(sc, s) for sc, s in ranked if sc >= 90]
    out: dict[str, Any] = {
        "query": query,
        "matches": [public(s) | {"score": round(sc, 1)} for sc, s in ranked[: max(1, min(limit, 25))]],
        "dictionary_generated_at": d.get("generated_at"),
        "deployed_code_guess": d.get("codebase", {}).get("co3ntrol-rs", {}).get("deployed_guess"),
    }
    if rules:
        out["rules"] = rules[:6]
    if not ranked and not rules:
        out["hint"] = (
            "No match. Try a GUI label (e.g. 'Vent/Bag Valve'), an IO tag (e.g. 'V17', 'B90'), a Prom name, "
            "or browse /workspace/ghost/systems/*.md"
        )
    return out


_COND_RE = re.compile(r"^(.+?)\s*(<=|>=|==|!=|<|>)\s*(-?\d+(?:\.\d+)?|true|false)$", re.I)
_RAW_PATH_RE = re.compile(r"^app(\.[A-Za-z_][\w]*)+$")


def resolve(spec: str, host: str) -> dict[str, Any]:
    """Map a user spec to a SQL expression for one host.

    Accepts dictionary id, field name, GUI label, IO tag, Prom name, or a raw
    `app.…` struct path, optionally with a comparison (`warm_tank_level < 14`).
    """
    spec = spec.strip()
    cond = None
    m = _COND_RE.match(spec)
    if m:
        spec, op, val = m.group(1).strip(), m.group(2), m.group(3)
        cond = (op, val)
    if _RAW_PATH_RE.match(spec):
        expr, sig = spec, None
    else:
        d = load()
        system = system_for_host(host)
        res = lookup(spec, limit=5, prefer_system=system or "")
        matches = res["matches"]
        if not matches or matches[0]["score"] < 50:
            raise LookupError(
                f"could not resolve signal '{spec}' for {host}"
                + (f"; closest: {[x['id'] for x in matches[:3]]}" if matches else "")
                + " — use lookup_signal or pass a raw app.… path"
            )
        sig = d["_by_id"][matches[0]["id"]]
        if sig.get("dims"):
            raise LookupError(
                f"'{sig['id']}' is per-instance ({sig['dims']}); pass a raw path like "
                f"{sig['sql']} with ids from instances={sig.get('instances')}"
            )
        expr = sig["sql"]
    label = spec if cond is None else f"{spec} {cond[0]} {cond[1]}"
    if cond is not None:
        op, val = cond
        sql_op = "=" if op == "==" else op
        expr = f"({expr} {sql_op} {val.upper() if val.lower() in ('true', 'false') else val})"
    return {"label": label, "expr": expr, "signal": public(sig) if sig else None, "is_condition": cond is not None}


def rules_for(system: str) -> list[dict[str, Any]]:
    d = load()
    rule_sys = "container" if system in ("bop", "dacs") else system
    return [r for r in d.get("rules", []) if r.get("system") == rule_sys]


def by_id(signal_id: str) -> dict[str, Any] | None:
    return load().get("_by_id", {}).get(signal_id)
